package com.example.cardioref_homepage;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.ImageView;

import androidx.activity.EdgeToEdge;
import androidx.appcompat.app.AppCompatActivity;
import androidx.cardview.widget.CardView;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;

import com.bumptech.glide.Glide;
import com.example.cardioref_homepage.activities.CDV_S;
import com.example.cardioref_homepage.activities.CardioDictionary;
import com.example.cardioref_homepage.activities.CardioNewsLetter;
import com.example.cardioref_homepage.activities.CardioQuiz;

public class MainActivity extends AppCompatActivity {
    CardView cv_cvds, cv_home_dictionary, cv_home_newsletter, cv_home_quiz;
    ImageView iv_cardio_home, iv_home_dictionary, iv_home_news, iv_home_quiz;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_main);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });
       // Objects.requireNonNull(getSupportActionBar()).setTitle("Home");

        cv_cvds = findViewById(R.id.cv_home_cvd);
        cv_home_dictionary = findViewById(R.id.cv_home_dictionary);
        cv_home_newsletter = findViewById(R.id.cv_home_newsletter);
        cv_home_quiz = findViewById(R.id.cv_home_quiz);
        iv_cardio_home = findViewById(R.id.iv_cardio_home);
        iv_home_dictionary = findViewById(R.id.iv_home_dictionary);
        iv_home_news = findViewById(R.id.iv_home_news);
        iv_home_quiz = findViewById(R.id.iv_home_quiz);

        Glide.with(MainActivity.this).load("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcToBhn6JlwkqMNIclYXpaThLTt8jyuOCblZeQ&s").into(iv_cardio_home);
        Glide.with(MainActivity.this).load("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRBnviiQqMpkWkp5XEucJHmMu7dDEpWr00y9A&s").into(iv_home_quiz);
        Glide.with(MainActivity.this).load("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSSLJWx0T5oxN9sOyIp2h-diJqkrVMonnfZGg&s").into(iv_home_news);
        Glide.with(MainActivity.this).load("data:image/jpeg;base64,").into(iv_home_dictionary);
        cv_cvds.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Intent intent = new Intent(MainActivity.this, CDV_S.class);
                startActivity(intent);
            }
        });
        cv_home_dictionary.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Intent intent = new Intent(MainActivity.this, CardioDictionary.class);
                startActivity(intent);
            }
        });
        cv_home_newsletter.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Intent intent = new Intent(MainActivity.this, CardioNewsLetter.class);
                startActivity(intent);
            }
        });

        cv_home_quiz.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Intent intent = new Intent(MainActivity.this, CardioQuiz.class);
                startActivity(intent);
            }
        });


    }


}